Section.CodeCell:
var player = world.Create(HList.From(
    new Name("Ari"),
    new Position(2, 3),
    new Velocity(1, -1),
    new Health(100)));

Console.WriteLine($"created {player.Get<Name>().Value} at {player.Get<Position>()}");

var position = new Position.View(player, world);
position.X += 5;
position.Y += 2;
Console.WriteLine($"moved through View to {player.Get<Position>()}");

player.Add(new Selected());
Console.WriteLine($"selected: {player.Contains<Selected>()}");
player.Remove<Selected>();

Notebook.Render($"{player.Get<Name>().Value} @ {player.Get<Position>()}  HP {player.Get<Health>().Value}");

public readonly record struct Name(string Value);
public partial record struct Position([Sia] float X, [Sia] float Y);
public readonly record struct Velocity(float X, float Y);
public partial record struct Health([Sia] int Value);
public readonly record struct Selected;
public readonly record struct Disabled;

Section.Paragraph:
Matchers.Of requires components; Matchers.Exclude rejects them;
matcher combinators build richer selections. A SystemBase owns a query, while
a stage gives one or more systems an explicit lifetime and tick order.

Section.CodeCell:
world.Create(HList.From(
    new Name("drone-a"), new Position(0, 0), new Velocity(2, 1)));
world.Create(HList.From(
    new Name("drone-b"), new Position(10, 10), new Velocity(-1, 0), new Disabled()));

var activeMovers = Matchers.Of<Name, Position, Velocity>()
    .And(Matchers.Exclude<Disabled>());
Console.WriteLine("active movers before the tick:");
foreach (var entity in world.Query(activeMovers)) {
    Console.WriteLine("  " + entity.Get<Name>().Value);
}

using var stage = SystemChain.Empty
    .Add<MovementSystem>()
    .CreateStage(world);
stage.Tick();

public readonly record struct Name(string Value);
public partial record struct Position([Sia] float X, [Sia] float Y);
public readonly record struct Velocity(float X, float Y);
public readonly record struct Disabled;

public sealed class MovementSystem() : SystemBase(
    Matchers.Of<Position, Velocity>().And(Matchers.Exclude<Disabled>()))
{
    public override void Execute(World world, IEntityQuery query)
    {
        foreach (var entity in query) {
            ref readonly var velocity = ref entity.Get<Velocity>();
            var position = new Position.View(entity, world);
            position.X += velocity.X;
            position.Y += velocity.Y;
        }
        Console.WriteLine($"MovementSystem updated {query.Count} entity/entities.");
    }
}

using var stage = SystemChain.Empty
    .Add<PositionChangedSystem>()
    .CreateStage(world);

var beacon = world.Create(HList.From(
    new Name("beacon"), new Position(0, 0)));
new Position.View(beacon, world) { X = 8, Y = 13 };
stage.Tick();

public readonly record struct Name(string Value);
public partial record struct Position([Sia] float X, [Sia] float Y);

public sealed class PositionChangedSystem() : SystemBase(
    Matchers.Of<Name, Position>(),
    EventUnion.Of<Position.SetX, Position.SetY>())
{
    public override void Execute(World world, IEntityQuery query)
    {
        foreach (var entity in query) {
            Console.WriteLine(
                $"reacted: {entity.Get<Name>().Value} -> {entity.Get<Position>()}");
        }
    }
}

var enemy = world.Create().AddBundle(new ActorBundle(
    new Name("slime"),
    new Position(4, 4),
    new Velocity(0, 0),
    new Health(30)));

using var stage = SystemChain.Empty
    .Add<DamageLogSystem>()
    .CreateStage(world);

var before = enemy.Get<Health>().Value;
enemy.Execute(new Damage(7));
stage.Tick();
var after = enemy.Get<Health>().Value;
Console.WriteLine($"health after command: {after}");
Notebook.Render($"{enemy.Get<Name>().Value}: {before} HP -> {after} HP");

public readonly record struct Name(string Value);
public partial record struct Position([Sia] float X, [Sia] float Y);
public readonly record struct Velocity(float X, float Y);
public partial record struct Health([Sia] int Value);

[SiaBundle]
public partial record struct ActorBundle(
    Name Name, Position Position, Velocity Velocity, Health Health);

public readonly record struct Damage(int Amount) : ICommand
{
    public void Execute(World world, Entity target)
        => new Health.View(target, world).Value -= Amount;
}

public sealed class DamageLogSystem() : SystemBase(
    Matchers.Of<Name, Health>(),
    EventUnion.Of<Damage>())
{
    public override void Execute(World world, IEntityQuery query)
    {
        foreach (var entity in query) {
            Console.WriteLine($"damage observed for {entity.Get<Name>().Value}");
        }
    }
}

var clock = world.AcquireAddon<TutorialClock>();
clock.Advance(0.016f);
clock.Advance(0.016f);
Console.WriteLine($"frame {clock.Frame}, time {clock.Time:F3}s");
world.RemoveAddon<TutorialClock>();

public sealed class TutorialClock : IAddon
{
    public int Frame { get; private set; }
    public float Time { get; private set; }

    public void OnInitialize(World world)
        => Console.WriteLine("clock initialized");

    public void OnUninitialize(World world)
        => Console.WriteLine("clock released");

    public void Advance(float deltaTime)
    {
        Frame++;
        Time += deltaTime;
    }
}

using var stage = SystemChain.Empty
    .Add<SpawnWaveSystem>(() => new("slime", 2))
    .Add<SpawnWaveSystem>(() => new("goblin", 1))
    .CreateStage(world);

stage.Tick();
stage.Tick();

Console.WriteLine($"world now holds {world.Count} entities, all spawned by this cell.");

var census = new Dictionary<string, int>();
foreach (var entity in world.Query(Matchers.Of<Name>())) {
    var kind = entity.Get<Name>().Value.Split('-')[0];
    census[kind] = census.GetValueOrDefault(kind) + 1;
}
var lines = census
    .OrderByDescending(pair => pair.Value)
    .Select(pair => $"  {pair.Key,-8} {new string('#', pair.Value)} {pair.Value}");
Notebook.Render($"world census ({world.Count} total):\n" + string.Join('\n', lines));

public readonly record struct Name(string Value);
public partial record struct Position([Sia] float X, [Sia] float Y);
public readonly record struct Velocity(float X, float Y);
public partial record struct Health([Sia] int Value);

[SiaBundle]
public partial record struct ActorBundle(
    Name Name, Position Position, Velocity Velocity, Health Health);

public sealed class SpawnWaveSystem(string kind, int count) : SystemBase(Matchers.Any)
{
    public override void Execute(World world, IEntityQuery query)
    {
        for (var i = 0; i < count; i++) {
            world.Create().AddBundle(new ActorBundle(
                new Name($"{kind}-{i}"), new Position(0, 0), new Velocity(0, 0), new Health(20)));
        }
        Console.WriteLine($"spawned {count} {kind}(s)");
    }
}
